# Check connectivity - what all 2s are connected together
from collections import deque

def get_connected_component(grid, start_pos):
    if start_pos[0] < 0 or start_pos[0] >= len(grid):
        return set()
    if start_pos[1] < 0 or start_pos[1] >= len(grid[0]):
        return set()
    if grid[start_pos[0]][start_pos[1]] != 2:
        return set()

    result = {start_pos}
    queue = deque([start_pos])

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) not in result and 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 2:
                    result.add((nr, nc))
                    queue.append((nr, nc))
    return result

# Find all connected components
